const delay = (ms, value) => new Promise((resolve) => setTimeout(resolve, ms, value));

async function main() {
  const answers = [delay(40, "slow"), delay(10, "fast")];
  for await (const answer of answers) {
    console.log(answer);
  }
  console.log("done");
}

setTimeout(() => console.log("timer"), 20);
main();
